import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BFMro0Mr.js";const u=JSON.parse('{"title":"Prispievanie","description":"Ako prispieť do Nette API a do tejto dokumentácie: spustenie testov a e2e kontrol príkladov, úprava diagramov a lokálny náhľad dokumentácie.","frontmatter":{"title":"Prispievanie","description":"Ako prispieť do Nette API a do tejto dokumentácie: spustenie testov a e2e kontrol príkladov, úprava diagramov a lokálny náhľad dokumentácie."},"headers":[],"relativePath":"sk/contributing.md","filePath":"sk/contributing.md","lastUpdated":1793392944000}'),o={name:"sk/contributing.md"};function n(r,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Pravidlá prispievania sa vedú po anglicky, rovnako ako v repozitári. Časť o dokumentácii nižšie je po slovensky.</p></div><h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Contributions are <strong>welcome</strong> and will be fully <strong>credited</strong>.</p><p>We accept contributions via Pull Requests on <a href="https://github.com/tomaj/nette-api" target="_blank" rel="noreferrer">Github</a>.</p><h2 id="pull-requests" tabindex="-1">Pull Requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull Requests&quot;">​</a></h2><ul><li><p><strong><a href="https://github.com/php-fig/fig-standards/blob/master/accepted/PSR-2-coding-style-guide.md" target="_blank" rel="noreferrer">PSR-2 Coding Standard</a></strong> - The easiest way to apply the conventions is to install <a href="http://pear.php.net/package/PHP_CodeSniffer" target="_blank" rel="noreferrer">PHP Code Sniffer</a>.</p></li><li><p><strong>Add tests!</strong> - Your patch won&#39;t be accepted if it doesn&#39;t have tests.</p></li><li><p><strong>Document any change in behaviour</strong> - Make sure the <code>README.md</code> and any other relevant documentation are kept up-to-date.</p></li><li><p><strong>Consider our release cycle</strong> - We try to follow <a href="http://semver.org/" target="_blank" rel="noreferrer">SemVer v2.0.0</a>. Randomly breaking public APIs is not an option.</p></li><li><p><strong>Create feature branches</strong> - Don&#39;t ask us to pull from your master branch.</p></li><li><p><strong>One pull request per feature</strong> - If you want to do more than one thing, send multiple pull requests.</p></li><li><p><strong>Send coherent history</strong> - Make sure each individual commit in your pull request is meaningful. If you had to make multiple intermediate commits while developing, please <a href="http://www.git-scm.com/book/en/v2/Git-Tools-Rewriting-History#Changing-Multiple-Commit-Messages" target="_blank" rel="noreferrer">squash them</a> before submitting.</p></li></ul><h2 id="running-tests" tabindex="-1">Running Tests <a class="header-anchor" href="#running-tests" aria-label="Permalink to &quot;Running Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Coverage reports (<code>build/logs/clover.xml</code>, <code>build/coverage/</code>) are opt-in and need Xdebug:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage</span></span></code></pre></div><p><strong>Happy coding</strong>!</p><h2 id="tato-dokumentacia" tabindex="-1">Táto dokumentácia <a class="header-anchor" href="#tato-dokumentacia" aria-label="Permalink to &quot;Táto dokumentácia&quot;">​</a></h2><p>Web je v <code>docs/</code>, postavený na VitePress, Node 22:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # http://localhost:5173/nette-api/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:links</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # kontrola odkazov v zostavenom webe</span></span></code></pre></div><ul><li>Kód na stránkach príkladov pochádza z projektov v <code>examples/</code> cez <code>&lt;&lt;&lt; @/../examples/...</code>; meňte projekt, nie stránku. Každý projekt má <code>e2e.sh</code>, ktorý spúšťa CI.</li><li>Každá anglická stránka má slovenské dvojča v <code>docs/sk/</code>; <code>npm run check</code> zlyhá, keď niektoré chýba.</li><li>Diagramy sú Excalidraw súbory v <code>docs/diagrams/</code>, vykreslené do svetlého a tmavého SVG cez <code>npm run diagrams</code>.</li><li>Každý pull request dostane náhľad na <code>https://tomaj.github.io/nette-api/pr-preview/pr-&lt;number&gt;/</code>.</li></ul><h2 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h2><h3 id="ako-spustim-testy" tabindex="-1">Ako spustím testy? <a class="header-anchor" href="#ako-spustim-testy" aria-label="Permalink to &quot;Ako spustím testy?&quot;">​</a></h3><p><code>composer test</code> spustí PHPUnit. <code>composer coverage</code> navyše zapíše reporty pokrytia do <code>build/</code> (potrebuje Xdebug). Každý projekt príkladu má aj <code>e2e.sh</code>, pozrite si <a href="/nette-api/pr-preview/pr-238/sk/examples/">Príklady</a>.</p><h3 id="musim-so-zmenou-upravit-aj-dokumentaciu" tabindex="-1">Musím so zmenou upraviť aj dokumentáciu? <a class="header-anchor" href="#musim-so-zmenou-upravit-aj-dokumentaciu" aria-label="Permalink to &quot;Musím so zmenou upraviť aj dokumentáciu?&quot;">​</a></h3><p>Áno, zmena správania potrebuje upravenú dokumentáciu, po anglicky aj po slovensky.</p><h3 id="ako-uvidim-zmenu-dokumentacie-pred-zlucenim" tabindex="-1">Ako uvidím zmenu dokumentácie pred zlúčením? <a class="header-anchor" href="#ako-uvidim-zmenu-dokumentacie-pred-zlucenim" aria-label="Permalink to &quot;Ako uvidím zmenu dokumentácie pred zlúčením?&quot;">​</a></h3><p>Spustite <code>npm run docs:dev</code> v <code>docs/</code>, alebo otvorte náhľad, ktorý dostane každý pull request.</p>`,22)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
